# module tkgrep.main
import std.io as io
import std.file as file
import std.str as str
import std.args as args


class greperr(SumType):  # holds exactly one of the variants below
    usage: str
    fileerr: str
    nopattern: None


@dataclass
class opts:
    pattern: str
    path: str
    ignorecase: bool
    countonly: bool
    nolinenum: bool
    invert: bool


def printusage() -> int:
    io.println("usage: tkgrep <pattern> <file>")
    io.println("")
    io.println("search for lines matching <pattern> in <file>")
    io.println("prints matching lines with line numbers.")
    io.println("")
    io.println("options:")
    io.println("  -i    case-insensitive matching")
    io.println("  -c    count matches only")
    io.println("  -n    suppress line numbers")
    io.println("  -v    invert match (print non-matching lines)")
    return 0


def parseargs() -> Result[opts, greperr]:
    ignorecase = False  # mut
    countonly = False  # mut
    nolinenum = False  # mut
    invert = False  # mut
    positional = []  # mut
    i = 1
    while i < int(args.count()):
        arg = args[i]
        if str.startswith(arg, "-"):
            if str.contains(arg, "i"):
                ignorecase = True
            if str.contains(arg, "c"):
                countonly = True
            if str.contains(arg, "n"):
                nolinenum = True
            if str.contains(arg, "v"):
                invert = True
        if str.startswith(arg, "-") == False:
            positional = positional.push(arg)
        i = i + 1
    if positional.len == 0:
        return greperr.nopattern(0)
    if positional.len < 2:
        return greperr.usage("need <pattern> and <file>")
    return opts(pattern=positional[0], path=positional[1], ignorecase=ignorecase, countonly=countonly, nolinenum=nolinenum, invert=invert)


def matches(line: str, pattern: str, ignorecase: bool) -> bool:
    if ignorecase:
        return str.contains(str.lower(line), str.lower(pattern))
    return str.contains(line, pattern)


def formatline(linenum: u64, line: str, shownum: bool) -> str:
    if shownum:
        buf = str.buf()
        str.add(buf, str.fromint(int(linenum)))
        str.add(buf, ":")
        str.add(buf, line)
        return str.done(buf)
    return line


def search(opts: opts) -> Result[u64, greperr]:
    match file.read(opts.path):
        case ok(v):
            content = v
        case err(e):
            return greperr.fileerr(str.concat("cannot read file: ", opts.path))
    lines = str.split(content, "\n")
    nlines = int(lines.len)  # mut
    if nlines > 0 and str.endswith(content, "\n"):
        nlines = nlines - 1
    count = 0  # mut
    shownum = opts.nolinenum == False
    i = 0
    while i < nlines:
        line = lines[i]
        hit = matches(line, opts.pattern, opts.ignorecase)
        show = hit  # mut
        if opts.invert:
            show = hit == False
        if show:
            count = count + 1
            if opts.countonly == False:
                linenum = u64(i + 1)
                io.println(formatline(linenum, line, shownum))
        i = i + 1
    if opts.countonly:
        io.println(str.fromint(int(count)))
    return u64(count)


def reporterr(e: greperr, showusage: bool) -> int:
    match e:
        case usage(msg):
            io.eprintln(str.concat("tkgrep: ", msg))
        case fileerr(msg):
            io.eprintln(str.concat("tkgrep: ", msg))
        case nopattern(z):
            io.eprintln("tkgrep: need <pattern> and <file>")
    if showusage:
        printusage()
    return 2


def main() -> int:
    match parseargs():
        case ok(o):
            opts = o
        case err(e):
            return reporterr(e, True)
    match search(opts):
        case ok(c):
            count = c
        case err(e):
            return reporterr(e, False)
    if count == 0:
        return 1
    return 0
